INSERT INTO questions (professions, course, topic, category, subtopic, difficulty, question_type, question_text, options, correct_answer, explanation, region, high_yield, year_level, source_reference) VALUES
('{"medicine"}','Medicine','Haematology','Pharmacology','Iron Therapy','easy','flashcard','What is the mechanism of action of oral ferrous sulfate in treating iron-deficiency anaemia?','["Ferrous sulfate (Fe2+) is absorbed in the duodenum and proximal jejunum via the divalent metal transporter 1 (DMT-1). Once absorbed, iron is stored as ferritin or transported bound to transferrin for use in haemoglobin synthesis and other iron-dependent processes."]','A','Fe2+ (ferrous) is better absorbed than Fe3+ (ferric). Acidic environment (vitamin C) enhances absorption.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Haematology','Pharmacology','Iron Therapy','medium','flashcard','When is intravenous (IV) iron preferred over oral iron supplementation?','["IV iron is preferred when: (1) oral iron is not tolerated due to GI side effects, (2) oral absorption is impaired (inflammatory bowel disease, post-gastrectomy, coeliac disease), (3) rapid iron repletion is needed (e.g. preoperative), (4) chronic kidney disease patients on haemodialysis, (5) ongoing blood loss exceeds what oral iron can replace, (6) non-compliance with oral regimens."]','A','Mnemonic: GRAINS -- GI intolerance, Renal disease (CKD/HD), Absorption failure, Inadequate response to oral, Need for speed, Surgery prep.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Haematology','Pharmacology','Iron Therapy','easy','flashcard','What are the common side effects of oral iron supplementation?','["Gastrointestinal: nausea, vomiting, epigastric pain, constipation (most common), diarrhoea, dark/black stools. These effects are dose-dependent and related to the amount of elemental iron released in the GI tract. Taking iron with food reduces GI side effects but decreases absorption."]','A','Black stools with oral iron = normal; distinguish from melaena (upper GI bleed) by checking for other bleeding signs.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Haematology','Pharmacology','Iron Therapy','medium','flashcard','Name three IV iron formulations and one distinguishing feature of each.','["(1) Iron sucrose -- low risk of anaphylaxis, used in CKD/haemodialysis; given as small repeated doses. (2) Ferric carboxymaltose -- can be given as a single large dose up to 1000 mg, convenient. (3) Iron dextran -- highest risk of anaphylaxis, requires test dose. (4) Ferumoxytol -- approved for CKD; rapid infusion possible."]','A','Ferric carboxymaltose (Ferinject) is increasingly preferred for IBD and postpartum anaemia due to single high-dose convenience.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Haematology','Pharmacology','Iron Therapy','hard','flashcard','How do you calculate total iron deficit and the dose of IV iron required?','["Total iron deficit (mg) = Body weight (kg) x (Target Hb - Actual Hb in g/dL) x 2.4 + 500 mg for iron stores. This is the Ganzoni formula. The 2.4 factor accounts for the amount of iron in haemoglobin per kg body weight per g/dL Hb. The 500 mg represents iron stores to be replenished."]','A','Ganzoni formula. In practice, weight-based dosing tables are often used instead to simplify calculation.','universal',false,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Haematology','Pharmacology','Iron Therapy','medium','flashcard','What drug interactions reduce oral iron absorption?','["Proton pump inhibitors and antacids raise gastric pH reducing Fe3+ to Fe2+ conversion; tetracyclines and fluoroquinolones chelate iron (space by 2 hours); calcium supplements; H2 blockers. Vitamin C (ascorbic acid) enhances iron absorption by maintaining Fe2+ state."]','A','Iron should be taken on an empty stomach for best absorption; if not tolerated, take with a small amount of food but avoid dairy, antacids, or calcium.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Haematology','Pharmacology','Iron Therapy','easy','flashcard','What is the expected haemoglobin response to oral iron therapy and when should reticulocytosis appear?','["Reticulocytosis appears within 3-5 days of starting iron therapy, peaking at 7-10 days -- the earliest sign of response. Haemoglobin rises by approximately 1 g/dL per week. Full correction of anaemia takes 4-8 weeks; iron stores should be replenished for a further 3-6 months after Hb normalises."]','A','Early sign = reticulocytosis at day 5-7. Hb up 1 g/dL/week. Continue 3-6 months after Hb normal to restore stores.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Haematology','Pharmacology','Iron Therapy','hard','flashcard','What is the management of acute iron toxicity (iron overdose)?','["Stages: (1) GI phase 0-6h: vomiting, haematemesis, diarrhoea. (2) Apparent recovery 6-24h. (3) Systemic toxicity 24-48h: shock, metabolic acidosis, hepatic failure. (4) Late: GI strictures. Treatment: gastric lavage if large ingestion within 1h; Deferoxamine IV (iron chelator, binds free iron, excreted in urine turning it orange -- vin rose urine); supportive care."]','A','Deferoxamine is the chelating antidote for iron overdose. Vin rose urine = deferoxamine working.','universal',false,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Haematology','Pharmacology','Iron Therapy','medium','flashcard','Why is iron supplementation particularly important in CKD patients on erythropoiesis-stimulating agents (ESAs)?','["ESAs stimulate rapid red blood cell production, dramatically increasing iron demand. Without adequate iron stores, ESAs cannot be effective -- functional iron deficiency occurs even if serum ferritin is normal. IV iron is preferred in CKD/haemodialysis patients because oral absorption is reduced due to elevated hepcidin levels, and IV iron rapidly replenishes stores needed for ESA-driven erythropoiesis."]','A','Target ferritin >200 ug/L and TSAT >20% in CKD patients on ESAs. Hepcidin blocks iron release from stores.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Haematology','Pharmacology','Iron Therapy','easy','flashcard','What is the elemental iron content of ferrous sulfate, ferrous gluconate, and ferrous fumarate?','["Ferrous sulfate (FeSO4): approximately 20% elemental iron (200 mg tablet = approximately 65 mg elemental iron). Ferrous gluconate: approximately 12% elemental iron. Ferrous fumarate: approximately 33% elemental iron (highest). Standard daily dose goal: 150-200 mg elemental iron per day in divided doses."]','A','Mnemonic: Fumarate is Fullest (33%), Sulfate is Standard (20%), Gluconate is Gentle/lowest (12%).','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Haematology','Pharmacology','B12 & Folate Supplements','easy','flashcard','What is the mechanism of action of vitamin B12 (cobalamin) in haematopoiesis?','["Vitamin B12 (cobalamin) is a cofactor for two key enzymes: (1) Methionine synthase -- converts homocysteine to methionine, regenerating tetrahydrofolate (THF) needed for DNA synthesis. (2) Methylmalonyl-CoA mutase -- converts methylmalonyl-CoA to succinyl-CoA (important for neurological function). Deficiency impairs DNA synthesis causing megaloblastic anaemia and demyelination."]','A','B12 deficiency causes megaloblastic anaemia AND subacute combined degeneration of the cord (SACD). Folate deficiency causes anaemia ONLY -- no neurological features.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Haematology','Pharmacology','B12 & Folate Supplements','medium','flashcard','What is the difference between cyanocobalamin and hydroxocobalamin?','["Cyanocobalamin: synthetic form; must be converted in the body to active forms (methylcobalamin, adenosylcobalamin); cheaper; used in IM injections for pernicious anaemia. Hydroxocobalamin: natural form; longer half-life, retained better in tissues; preferred in UK for IM B12 therapy and as antidote to cyanide poisoning (binds CN-). Methylcobalamin: active form; used in some oral supplements; crosses BBB more readily."]','A','UK preferred B12 for IM injection = hydroxocobalamin (longer lasting). Hydroxocobalamin also treats cyanide poisoning.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Haematology','Pharmacology','B12 & Folate Supplements','medium','flashcard','When should intramuscular B12 be given instead of oral B12?','["IM B12 is indicated when: (1) Pernicious anaemia (lack of intrinsic factor -- oral absorption requires IF). (2) Gastric atrophy/post-gastrectomy. (3) Terminal ileal disease or resection (site of B12 absorption). (4) Malabsorption syndromes. High-dose oral B12 (1000-2000 ug/day) can be used when deficiency is dietary only (e.g. vegans), as passive absorption without IF occurs at high doses."]','A','Pernicious anaemia = autoimmune destruction of parietal cells => no intrinsic factor => B12 malabsorption => must give IM (bypasses gut).','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Haematology','Pharmacology','B12 & Folate Supplements','easy','flashcard','What is the standard IM hydroxocobalamin regimen for pernicious anaemia?','["Loading: 1000 ug IM every other day for 6 doses (2 weeks) to replenish stores. Maintenance: 1000 ug IM every 3 months for life (as underlying cause -- lack of intrinsic factor -- cannot be corrected). Neurological symptoms may improve slowly over 3-6 months; some deficits may be permanent if prolonged."]','A','Pernicious anaemia needs lifelong IM B12. Loading for 2 weeks, then 3-monthly for life.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Haematology','Pharmacology','B12 & Folate Supplements','medium','flashcard','What is the role of folic acid in haematopoiesis and what is the daily requirement?','["Folic acid (folate) is converted to tetrahydrofolate (THF), the active form. THF acts as a one-carbon donor for purine and thymidylate synthesis -- both essential for DNA replication. Rapidly dividing cells (haematopoietic precursors) are particularly dependent. Deficiency leads to megaloblastic anaemia. Daily requirement: approximately 400 ug/day (general); 5 mg/day in pregnancy or haemolytic states."]','A','Folate deficiency leads to megaloblastic anaemia but NO neurological features (unlike B12). Neural tube defects if deficient in early pregnancy.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Haematology','Pharmacology','B12 & Folate Supplements','hard','flashcard','Why must B12 deficiency be ruled out before treating with folic acid alone?','["Treating isolated folic acid deficiency with folic acid will correct the anaemia but will NOT correct the neurological features of B12 deficiency, and may allow subacute combined degeneration of the spinal cord (SACD) to progress undetected and become irreversible. This is called the masking effect -- folic acid masks haematological manifestations of B12 deficiency while neurological deterioration continues."]','A','Always check B12 before giving folic acid. B12 deficiency = SACD (posterior and lateral column demyelination). Folic acid masks anaemia but not neuro damage.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Haematology','Pharmacology','B12 & Folate Supplements','easy','flashcard','In which patients is high-dose folic acid (5 mg/day) recommended?','["High-dose folic acid 5 mg/day is recommended in: (1) Haemolytic anaemias (sickle cell disease, thalassaemia, hereditary spherocytosis) -- high RBC turnover increases demand. (2) Pregnancy -- 5 mg if previous neural tube defect, diabetes, anti-epileptic drugs, or malabsorption. (3) Methotrexate therapy -- as leucovorin rescue. (4) Dialysis patients. (5) Severe malnutrition."]','A','5 mg folic acid = haemolytic anaemia, high-risk pregnancy, methotrexate toxicity. Standard prophylaxis in pregnancy = 400 ug.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Haematology','Pharmacology','B12 & Folate Supplements','medium','flashcard','What drugs can cause B12 or folate deficiency and by what mechanism?','["B12 deficiency: Metformin (reduces B12 absorption from terminal ileum via Ca2+-dependent mechanism); Proton pump inhibitors (reduce acid needed for B12 release from food); Nitrous oxide (irreversibly oxidises B12, blocks methionine synthase). Folate deficiency: Methotrexate (dihydrofolate reductase inhibitor -- blocks THF synthesis); Trimethoprim (DHFR inhibitor); Phenytoin/carbamazepine (impair folate absorption)."]','A','Methotrexate toxicity rescued by leucovorin (folinic acid -- bypasses DHFR). Metformin causes B12 deficiency -- check B12 annually in long-term users.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Haematology','Pharmacology','B12 & Folate Supplements','easy','flashcard','What blood film findings suggest megaloblastic anaemia due to B12/folate deficiency?','["Peripheral blood film: Macrocytosis (MCV >100 fL), oval macrocytes (macro-ovalocytes), hypersegmented neutrophils (5+ lobes in at least 5% of neutrophils or any neutrophil with 6 or more lobes). Bone marrow: Hypercellular with giant metamyelocytes and megaloblasts. Other lab findings: Raised LDH and bilirubin (ineffective erythropoiesis), low reticulocyte count."]','A','Hypersegmented neutrophils = hallmark of megaloblastic anaemia. Can appear before Hb drops. Macro-ovalocytes are most specific RBC change.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Haematology','Pharmacology','B12 & Folate Supplements','medium','flashcard','What is subacute combined degeneration of the cord (SACD) and which vitamin deficiency causes it?','["SACD is a neurological complication of vitamin B12 deficiency. It involves demyelination of the posterior columns (loss of vibration and proprioception) and lateral corticospinal tracts (upper motor neurone signs -- spasticity, hyperreflexia). Clinically: sensory ataxia, proprioception loss, positive Romberg, pyramidal signs. Caused by impaired methylmalonyl-CoA mutase activity leading to myelin instability. Treatment: IM B12 -- partial recovery possible but severe prolonged cases may be irreversible."]','A','B12 deficiency = SACD = posterior columns + lateral corticospinal tracts. Folate deficiency = no SACD. B12 NOT folic acid!','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Haematology','Pharmacology','Erythropoiesis-Stimulating Agents','easy','flashcard','What is the mechanism of action of erythropoietin (EPO) and erythropoiesis-stimulating agents (ESAs)?','["Erythropoietin (EPO) is a glycoprotein hormone produced by peritubular cells of the kidney in response to hypoxia. It binds EPO receptors (EpoR) on erythroid progenitor cells in bone marrow, activates JAK2/STAT5 signalling, and promotes survival, proliferation, and differentiation of erythroid progenitors, increasing RBC production. Epoetin alfa and darbepoetin alfa are recombinant ESAs that mimic endogenous EPO."]','A','Kidney senses hypoxia => EPO => bone marrow stimulated => more RBCs. ESAs = recombinant EPO analogues.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Haematology','Pharmacology','Erythropoiesis-Stimulating Agents','easy','flashcard','What are the main indications for erythropoiesis-stimulating agents?','["(1) Anaemia of chronic kidney disease (CKD) -- most common indication; (2) Chemotherapy-induced anaemia in non-myeloid malignancies; (3) Pre-surgical autologous blood donation; (4) Anaemia due to zidovudine (AZT) in HIV; (5) Myelodysplastic syndrome (MDS) -- low EPO levels. ESAs are NOT indicated for iron-deficiency anaemia or anaemia due to B12/folate deficiency."]','A','Main ESA indication = CKD anaemia. Also chemotherapy anaemia. NOT for iron or B12/folate deficiency.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Haematology','Pharmacology','Erythropoiesis-Stimulating Agents','medium','flashcard','What is the difference between epoetin alfa and darbepoetin alfa?','["Epoetin alfa (Eprex): identical to endogenous EPO; half-life approximately 4-13h IV, approximately 24h SC; given 3x weekly or weekly. Darbepoetin alfa (Aranesp): hyperglycosylated analogue with 2 extra N-linked carbohydrate chains; half-life approximately 25-49h IV; given weekly or every 2 weeks. Longer half-life of darbepoetin allows less frequent dosing. Both require adequate iron stores to be effective."]','A','Darbepoetin = longer duration (hyperglycosylated = longer half-life). Less frequent injections needed.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Haematology','Pharmacology','Erythropoiesis-Stimulating Agents','medium','flashcard','What are the key adverse effects of erythropoiesis-stimulating agents?','["(1) Hypertension -- most common; increased blood viscosity and vasoconstriction from rapid Hb rise; requires antihypertensive treatment. (2) Thrombosis -- DVT, stroke, MI, AV fistula thrombosis (important in haemodialysis). (3) Pure red cell aplasia (PRCA) -- rare; antibody-mediated neutralisation of EPO (associated with SC epoetin alfa). (4) Tumour progression -- ESAs can stimulate tumour growth if EPO receptors are expressed on cancer cells. (5) Flu-like symptoms."]','A','ESA risks: Hypertension + Thrombosis + PRCA. Target Hb 10-12 g/dL in CKD (higher targets increase CV events -- TREAT and CHOIR trials).','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Haematology','Pharmacology','Erythropoiesis-Stimulating Agents','hard','flashcard','What is pure red cell aplasia (PRCA) and which ESA and route most commonly causes it?','["PRCA is a rare but serious complication where antibodies develop against EPO (both exogenous and endogenous), causing severe anaemia with markedly reduced erythroid precursors in bone marrow. Most commonly associated with subcutaneous epoetin alfa (Eprex), particularly after a formulation change in 1999. Management: stop ESA immediately, immunosuppressive therapy (corticosteroids, ciclosporin), and consider renal transplantation. Anti-EPO antibodies test confirms diagnosis."]','A','PRCA = anti-EPO antibodies = rare, severe, most linked to SC epoetin alfa. Stop ESA, give immunosuppression.','universal',false,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Haematology','Pharmacology','Erythropoiesis-Stimulating Agents','medium','flashcard','What is the target haemoglobin range when using ESAs in CKD, and why does targeting higher Hb cause harm?','["Target Hb in CKD on ESAs: 10-12 g/dL (KDIGO guidelines). Targeting Hb >13 g/dL is associated with increased risk of cardiovascular events (stroke, MI, heart failure), thromboembolism, and death -- shown in TREAT, CHOIR, and CREATE trials. Mechanism: higher Hb increases blood viscosity and thrombotic tendency, and may indicate EPO resistance driving supraphysiological doses which have off-target effects."]','A','CHOIR/TREAT trials: targeting Hb 13-14 g/dL with ESAs => more strokes, CV events, no QoL benefit. Target 10-12 g/dL only.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Haematology','Pharmacology','Erythropoiesis-Stimulating Agents','easy','flashcard','Why must iron stores be adequate before and during ESA therapy?','["ESAs stimulate rapid erythropoiesis, massively increasing iron demand for haemoglobin synthesis. Without adequate iron, the bone marrow cannot produce functional RBCs -- this is functional iron deficiency (low TSAT <20% even with normal ferritin). ESA response is blunted and iron-restricted erythropoiesis occurs. IV iron supplementation alongside ESAs improves response, reduces ESA dose needed."]','A','No iron = ESAs do not work. Check TSAT and ferritin before starting ESA. IV iron preferred in CKD patients on haemodialysis.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Haematology','Pharmacology','Erythropoiesis-Stimulating Agents','hard','flashcard','What are the causes of ESA resistance (inadequate response to ESAs)?','["Definition: inadequate Hb response despite ESA dose >300 IU/kg/week epoetin. Causes (FINEST mnemonic): F -- Iron deficiency (functional or absolute); I -- Infection/Inflammation (hepcidin upregulation blocks iron release); N -- Non-compliance; E -- EPO antibodies (PRCA); S -- Secondary haematological disease (myeloma, MDS); T -- Toxicity (aluminium toxicity, osteitis fibrosa in hyperparathyroidism); also: vitamin B12/folate deficiency, haemolysis, bleeding, inadequate dialysis."]','A','Commonest cause of ESA resistance = iron deficiency. Rule out FINEST causes. Hepcidin blocks iron in inflammation = functional iron deficiency.','universal',false,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Haematology','Pharmacology','Erythropoiesis-Stimulating Agents','medium','flashcard','What are the contraindications to ESA therapy?','["Absolute contraindications: (1) Uncontrolled hypertension; (2) Pure red cell aplasia (PRCA) from prior ESA use; (3) Known hypersensitivity to ESA. Relative contraindications/cautions: (1) Active malignancy where cure is intended (may stimulate tumour growth); (2) Thrombotic risk factors (recent MI, stroke, DVT); (3) Haemoglobin >12 g/dL. ESAs should NOT be used to treat chemotherapy anaemia when the aim is curative -- increased mortality shown."]','A','ESA contraindicated in: uncontrolled HTN, PRCA, active cancer with curative intent, Hb already adequate. Thrombosis risk must be assessed.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Haematology','Pharmacology','Erythropoiesis-Stimulating Agents','easy','flashcard','Name two HIF-prolyl hydroxylase inhibitors (HIF-PHIs) used for anaemia of CKD and state their mechanism.','["HIF-PHIs (oral ESA alternatives): Examples -- Roxadustat, Daprodustat, Vadadustat. Mechanism: Inhibit hypoxia-inducible factor prolyl hydroxylase (HIF-PH) enzymes, preventing degradation of HIF-1 alpha, which accumulates and transcribes the EPO gene, increasing endogenous EPO production and erythropoiesis. Also improve iron availability by reducing hepcidin and increasing DMT-1 expression. Oral administration is an advantage over injectable ESAs."]','A','HIF-PHIs = oral pills that stimulate endogenous EPO. Roxadustat first in class. Inhibit HIF-PHD => stabilise HIF => EPO transcription.','universal',false,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Haematology','Pharmacology','Anticoagulants — Heparin & LMWHs','easy','flashcard','What is the mechanism of action of unfractionated heparin (UFH)?','["UFH is a naturally occurring glycosaminoglycan that binds antithrombin III (AT-III) and causes a conformational change that dramatically accelerates AT-III ability to inactivate coagulation factors -- primarily factor IIa (thrombin) and factor Xa (in a 1:1 ratio). UFH also inhibits factors IXa, XIa, XIIa. The heparin-AT-III complex is 1000x more potent than AT-III alone. UFH requires adequate AT-III to work."]','A','UFH + ATIII => inhibits IIa (thrombin) AND Xa equally. LMWH mostly inhibits Xa. Needs AT-III -- heparin resistance in AT-III deficiency.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Haematology','Pharmacology','Anticoagulants — Heparin & LMWHs','medium','flashcard','How does low molecular weight heparin (LMWH) differ from unfractionated heparin (UFH) in mechanism and monitoring?','["LMWH (enoxaparin, dalteparin, tinzaparin): shorter chains preferentially inhibit factor Xa but have insufficient chain length to simultaneously bind AT-III and thrombin. More predictable pharmacokinetics, SC bioavailability approximately 90%, half-life approximately 4-6h, eliminated renally. Monitoring: anti-Xa levels (not aPTT) if needed in renal failure, obesity, or pregnancy. UFH: both anti-IIa and anti-Xa; monitored by aPTT; erratic absorption; given IV or SC."]','A','UFH monitored by aPTT; LMWH monitored by anti-Xa (if at all). LMWH selectively inhibits Xa. UFH inhibits Xa and IIa equally.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Haematology','Pharmacology','Anticoagulants — Heparin & LMWHs','easy','flashcard','What is the reversal agent for heparin (UFH and LMWH), and how does it work?','["Protamine sulfate: a positively charged protein (from salmon sperm) that binds negatively charged heparin, forming an inactive complex. Reversal of UFH: 1 mg protamine per 100 units UFH given in last 2-4 hours (give slowly IV to avoid anaphylaxis, hypotension, pulmonary hypertension). Reversal of LMWH: protamine partially reverses (approximately 60% anti-Xa activity); 1 mg protamine per 1 mg enoxaparin (given within 8h) -- incomplete reversal."]','A','Protamine = heparin antidote. Positive charge binds negative charge of heparin = inactive complex. Only approximately 60% effective for LMWH.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Haematology','Pharmacology','Anticoagulants — Heparin & LMWHs','medium','flashcard','What is heparin-induced thrombocytopenia (HIT) and how is it managed?','["HIT is an immune-mediated complication of heparin. Type 1 HIT: non-immune, mild thrombocytopenia within 2 days, benign, self-limiting. Type 2 HIT (clinically significant): immune-mediated IgG antibodies against heparin-platelet factor 4 (hPF4) complex, leading to platelet activation, platelet consumption, and paradoxical THROMBOSIS. Management: (1) STOP all heparin immediately; (2) Start alternative anticoagulation -- argatroban or bivalirudin or danaparoid; (3) Do NOT give warfarin until platelets recover; (4) Test for anti-PF4 antibodies (ELISA)."]','A','HIT Type 2 paradox: low platelets + thrombosis (White clot syndrome). STOP heparin, start argatroban/bivalirudin. 4Ts score assesses probability.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Haematology','Pharmacology','Anticoagulants — Heparin & LMWHs','medium','flashcard','When should LMWH be used with caution or avoided, and what alternative is used?','["LMWH is renally cleared -- accumulates in renal failure (eGFR <30 mL/min/1.73m2) leading to increased bleeding risk. In severe renal impairment: use UFH (non-renal clearance, monitored by aPTT) or dose-adjusted LMWH with anti-Xa monitoring. Also use caution in: extremes of weight, pregnancy (serial anti-Xa monitoring required), mechanical heart valves (use UFH). Fondaparinux also renally cleared -- avoid if eGFR <30."]','A','LMWH contraindicated in severe renal failure (eGFR <30) -- use UFH instead. LMWH cleared by kidneys; UFH cleared by liver/reticuloendothelial system.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Haematology','Pharmacology','Anticoagulants — Heparin & LMWHs','easy','flashcard','What is fondaparinux and how does it differ from LMWH?','["Fondaparinux (Arixtra) is a synthetic pentasaccharide -- the minimal active unit of heparin that binds AT-III. It selectively inhibits factor Xa ONLY (unlike UFH which inhibits Xa and IIa; and unlike LMWH which mainly inhibits Xa). Given SC once daily; half-life approximately 17-21h; renally excreted. No protamine reversal (no licensed antidote). No risk of HIT (does not bind PF4). Used in ACS, VTE prevention and treatment."]','A','Fondaparinux = pure anti-Xa only. No HIT risk. No protamine reversal. Avoid in renal failure. Once daily SC -- convenient.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Haematology','Pharmacology','Anticoagulants — Heparin & LMWHs','medium','flashcard','What are the clinical indications for intravenous unfractionated heparin (UFH)?','["IV UFH is preferred when: (1) Rapid anticoagulation is needed (ACS, massive PE, large DVT); (2) Rapid reversal may be needed (protamine available); (3) Renal failure (UFH not renally cleared); (4) Patients undergoing surgery/procedures requiring frequent monitoring and dose titration; (5) Cardiopulmonary bypass; (6) Bridging therapy for patients with mechanical heart valves; (7) Perioperative setting where anticoagulation must be quickly stopped."]','A','IV UFH advantages: fast on, fast off, reversible, works in renal failure, continuous aPTT monitoring. Used in surgical and high-risk settings.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Haematology','Pharmacology','Anticoagulants — Heparin & LMWHs','hard','flashcard','What is the therapeutic aPTT range for UFH and how is the infusion adjusted?','["Therapeutic aPTT: 60-100 seconds (or 1.5-2.5x the control aPTT, typically 25-35s). Nomogram-based dose adjustments: If aPTT <45s increase bolus and rate; 45-59s increase rate; 60-100s maintain; 101-120s reduce rate; >120s stop infusion for 1h then reduce. Check aPTT 6h after any change. Therapeutic range prevents extension of clot while minimising bleeding risk."]','A','Therapeutic aPTT = 60-100s (1.5-2.5x control). Check 6h after dose change. Supratherapeutic => hold infusion and recheck.','universal',false,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Haematology','Pharmacology','Anticoagulants — Heparin & LMWHs','medium','flashcard','Name three direct thrombin inhibitors and their key clinical uses.','["(1) Argatroban: IV; hepatically metabolised; used in HIT (does not cross-react with heparin antibodies); good for renal failure. (2) Bivalirudin: IV; short half-life; used during PCI/ACS; mainly enzymatically degraded. (3) Dabigatran: oral; direct thrombin inhibitor; DOAC used for AF, VTE treatment and prevention; renally cleared; reversed by idarucizumab. Direct thrombin inhibitors do NOT require AT-III -- useful when AT-III deficiency is present."]','A','DTIs bypass AT-III -- work in AT-III deficiency and HIT. Argatroban for HIT (hepatic metabolism); dabigatran is the oral DTI (DOAC).','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Haematology','Pharmacology','Anticoagulants — Heparin & LMWHs','easy','flashcard','What is the therapeutic anti-Xa range for LMWH monitoring and when is monitoring required?','["Therapeutic anti-Xa range for LMWH (treatment dose, checked 4h post-dose): Enoxaparin 1 mg/kg BD: target 0.6-1.0 IU/mL; Enoxaparin 1.5 mg/kg OD: target 1.0-2.0 IU/mL. Monitoring indicated in: (1) Renal impairment (eGFR 30-60 mL/min); (2) Extremes of weight; (3) Pregnancy; (4) Neonates. Routine monitoring NOT required in average-weight adults with normal renal function."]','A','Anti-Xa checked 4h post LMWH dose. Monitoring in renal impairment, pregnancy, extremes of weight. Therapeutic range 0.6-1.0 IU/mL (BD dosing).','universal',false,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Haematology','Pharmacology','Anticoagulants — Warfarin','easy','flashcard','What is the mechanism of action of warfarin?','["Warfarin inhibits vitamin K epoxide reductase complex 1 (VKORC1), blocking the regeneration of vitamin K from its oxidised (epoxide) form back to the reduced (active) form. Reduced vitamin K is a cofactor for gamma-carboxylation of glutamate residues on clotting factors II, VII, IX, X and anticoagulant proteins C and S. Without active vitamin K, these factors are produced but non-functional (PIVKA). Warfarin affects synthesis, not existing factors."]','A','Warfarin blocks VKORC1 => no reduced Vit K => clotting factors II, VII, IX, X not activated. Also reduces proteins C and S -- hence initial procoagulant effect.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Haematology','Pharmacology','Anticoagulants — Warfarin','medium','flashcard','Which vitamin K-dependent clotting factor has the shortest half-life, and why does this matter clinically?','["Factor VII has the shortest half-life (approximately 6 hours). When warfarin is started, the INR rises initially because factor VII falls first -- but the patient is NOT yet fully anticoagulated (factors II, IX, X with longer half-lives are still active). This creates a dangerous window where INR appears therapeutic but clotting factors important for full anticoagulation are still present. This is why heparin should overlap warfarin for at least 5 days AND until INR is therapeutic for 2 consecutive days."]','A','Factor VII t1/2 = 6h (shortest). INR rises early from VII fall but not truly anticoagulated. Bridge with heparin 5 days minimum until INR stable x2.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Haematology','Pharmacology','Anticoagulants — Warfarin','easy','flashcard','What is the target INR range for different clinical indications for warfarin?','["INR 2.0-3.0: Non-valvular AF; DVT and PE treatment and secondary prevention; antiphospholipid syndrome (first thrombosis); tissue (bioprosthetic) heart valves (for 3 months); rheumatic mitral valve disease. INR 2.5-3.5: Mechanical mitral valve; mechanical aortic valve in high-risk patients; recurrent thromboembolism on INR 2-3; antiphospholipid syndrome with arterial thrombosis. Standard target: INR 2.5."]','A','Standard INR 2-3 for most. Mechanical valves = 2.5-3.5. Higher INR = higher bleeding risk. Bioprosthetic valve only needs 3 months of anticoagulation.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Haematology','Pharmacology','Anticoagulants — Warfarin','hard','flashcard','Name the key drug interactions with warfarin and their mechanisms.','["Warfarin is metabolised by CYP2C9 (main) and CYP3A4. INCREASE INR (bleeding risk): Inhibitors of CYP2C9/3A4 -- fluconazole, amiodarone, metronidazole, ciprofloxacin, clarithromycin. Broad-spectrum antibiotics reduce vitamin K producing gut bacteria. NSAIDs displace warfarin from albumin. DECREASE INR (clotting risk): Inducers of CYP2C9/3A4 -- rifampicin (most potent), carbamazepine, phenytoin, St John Wort, phenobarbitone. High-dose vitamin K foods (leafy greens) decrease INR. Aspirin causes bleeding risk without INR change."]','A','Amiodarone, metronidazole, fluconazole => raise INR (inhibit CYP2C9). Rifampicin => lowers INR (induces CYP). Complex interactions require frequent INR monitoring.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Haematology','Pharmacology','Anticoagulants — Warfarin','medium','flashcard','How do you manage warfarin reversal in different clinical scenarios?','["(1) INR 5-8, no bleeding: Withhold 1-2 doses, recheck INR. (2) INR >8, no bleeding/minor bleeding: Stop warfarin, give oral vitamin K 1-5 mg; recheck in 24h. (3) Major bleeding: Stop warfarin + IV vitamin K 10 mg + 4-factor Prothrombin Complex Concentrate (PCC -- contains II, VII, IX, X, protein C and S) for immediate reversal. (4) Life-threatening bleeding: as above -- PCC preferred over FFP (faster, lower volume). Fresh frozen plasma (FFP) is used if PCC unavailable."]','A','Major warfarin bleed = STOP + IV Vit K 10 mg + 4-factor PCC (fastest reversal). FFP only if PCC unavailable. PCC is factor concentrate -- faster than FFP.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Haematology','Pharmacology','Anticoagulants — Warfarin','medium','flashcard','What genetic polymorphisms affect warfarin dosing?','["(1) VKORC1 polymorphisms: Affect sensitivity to warfarin. VKORC1 -1639G>A: AA genotype requires low dose (approximately 3 mg/day); GG requires higher dose (approximately 6 mg/day). (2) CYP2C9 polymorphisms: Affect warfarin metabolism. CYP2C9*2 and *3 variants: reduced enzyme activity, slower warfarin clearance, lower dose needed. (3) CYP4F2*3 variant: affects vitamin K metabolism leading to need for higher warfarin dose. Pharmacogenomic-guided dosing improves time in therapeutic range."]','A','VKORC1 = warfarin sensitivity (pharmacodynamic). CYP2C9 = warfarin metabolism (pharmacokinetic). Both affect dose. Asians often more sensitive (VKORC1 AA common).','universal',false,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Haematology','Pharmacology','Anticoagulants — Warfarin','easy','flashcard','Why is warfarin initially procoagulant when started without heparin bridging?','["Warfarin inhibits synthesis of both procoagulant factors (II, VII, IX, X) AND anticoagulant proteins (Protein C and Protein S). Protein C has the shortest half-life (approximately 8 hours) among these, so Protein C falls first, creating an early net procoagulant state (loss of natural anticoagulation before loss of clotting factors). This is especially dangerous in patients with protein C deficiency, who may develop warfarin-induced skin necrosis. Solution: always overlap with heparin during warfarin initiation."]','A','Warfarin starts => protein C falls first (shortest t1/2 approximately 8h) => procoagulant window. BRIDGE with heparin x5 days. Protein C deficiency + warfarin = skin necrosis.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Haematology','Pharmacology','Anticoagulants — Warfarin','medium','flashcard','What is warfarin-induced skin necrosis and who is at risk?','["Warfarin-induced skin necrosis is a rare complication occurring 3-6 days after starting warfarin. Thrombosis of skin microvasculature leads to skin infarction and necrosis, typically in areas of adipose tissue (breasts, thighs, buttocks, abdomen). Caused by precipitous fall in Protein C relative to procoagulant factors, creating a hypercoagulable state. At risk: Hereditary protein C or protein S deficiency patients, antiphospholipid syndrome, very high starting doses of warfarin. Management: stop warfarin, give Protein C concentrate or FFP, start heparin."]','A','Warfarin skin necrosis = 3-6 days in. Areas of fat (breasts, buttocks). Risk = protein C deficiency. Treat = stop warfarin + heparin + Protein C concentrate.','universal',false,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Haematology','Pharmacology','Anticoagulants — Warfarin','easy','flashcard','What are the contraindications to warfarin therapy?','["Absolute contraindications: (1) Pregnancy -- warfarin crosses placenta; teratogenic in first trimester (warfarin embryopathy: nasal hypoplasia, stippled epiphyses); causes fetal haemorrhage in third trimester; use LMWH in pregnancy. (2) Active major bleeding. (3) Allergy/hypersensitivity. Relative contraindications: (1) Non-compliance (narrow therapeutic window, requires INR monitoring); (2) Recent CNS or ophthalmic surgery; (3) Severe hypertension (SBP >200 mmHg); (4) Significant fall risk; (5) Severe hepatic failure."]','A','Warfarin in pregnancy = ABSOLUTELY CONTRAINDICATED. Use LMWH instead. Warfarin embryopathy (1st trimester) = saddle nose, stippled bones.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Haematology','Pharmacology','Anticoagulants — Warfarin','medium','flashcard','How does the time in therapeutic range (TTR) relate to warfarin safety and efficacy?','["TTR (% of INR values within target range 2-3) is the key quality metric for warfarin therapy. TTR >70%: optimal -- associated with significantly reduced rates of stroke, bleeding, and thromboembolism. TTR <65%: consider switching to a DOAC (e.g. rivaroxaban, apixaban) if clinically appropriate. Factors reducing TTR: frequent diet changes (vitamin K), polypharmacy, non-compliance, intercurrent illness. Poor TTR is the main driver for choosing DOACs over warfarin in AF."]','A','TTR >70% = well-controlled warfarin. TTR <65% = consider switching to DOAC. UK NICE recommends DOAC as first-line for AF now.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Haematology','Pharmacology','Direct Oral Anticoagulants','easy','flashcard','What are the four direct oral anticoagulants (DOACs), their targets, and reversal agents?','["(1) Dabigatran (Pradaxa) -- direct thrombin (IIa) inhibitor; reversal: idarucizumab (Praxbind). (2) Rivaroxaban (Xarelto) -- direct factor Xa inhibitor; reversal: andexanet alfa or PCC. (3) Apixaban (Eliquis) -- direct factor Xa inhibitor; reversal: andexanet alfa or PCC. (4) Edoxaban (Lixiana) -- direct factor Xa inhibitor; reversal: andexanet alfa or PCC. No routine monitoring required (predictable pharmacokinetics); all have a renal excretion component."]','A','Mnemonic DRAE: Dabigatran (IIa), Rivaroxaban (Xa), Apixaban (Xa), Edoxaban (Xa). Dabigatran reversed by idarucizumab; Xa inhibitors by andexanet alfa.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Haematology','Pharmacology','Direct Oral Anticoagulants','medium','flashcard','What are the main clinical indications for DOACs?','["(1) Non-valvular atrial fibrillation (AF) -- stroke prevention (all four DOACs approved); (2) VTE treatment (DVT and PE) -- all four approved; (3) VTE prevention post orthopaedic surgery (rivaroxaban, apixaban, dabigatran); (4) Secondary VTE prevention (extended treatment); (5) ACS -- rivaroxaban 2.5 mg BD as adjunct to antiplatelet therapy (ATLAS-ACS 2). NOT approved for: mechanical heart valves (RE-ALIGN trial showed dabigatran inferior to warfarin); valvular AF (mitral stenosis or mechanical valves)."]','A','DOACs for: non-valvular AF, DVT/PE, post-ortho surgery VTE prophylaxis. NOT for mechanical heart valves. Low-dose rivaroxaban for ACS secondary prevention.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Haematology','Pharmacology','Direct Oral Anticoagulants','medium','flashcard','How does dabigatran differ from the other DOACs pharmacokinetically?','["Dabigatran is a prodrug -- dabigatran etexilate is absorbed orally and hydrolysed by esterases to active dabigatran. Key differences: (1) Prodrug (others are active drugs); (2) NOT metabolised by CYP450 (others are CYP3A4 substrates); (3) P-glycoprotein substrate (avoid strong P-gp inhibitors e.g. dronedarone, rifampicin); (4) Highest renal excretion 80% (avoid if eGFR <30); (5) Only DOAC with specific antibody antidote (idarucizumab -- binds dabigatran with 350x affinity vs thrombin); (6) Low bioavailability approximately 6.5% (capsule must not be opened)."]','A','Dabigatran: prodrug, no CYP metabolism, 80% renal (avoid CKD), P-gp substrate, capsule cannot be opened, reversed by idarucizumab.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Haematology','Pharmacology','Direct Oral Anticoagulants','medium','flashcard','What renal function thresholds guide DOAC prescribing?','["Avoid in severe renal failure (eGFR thresholds): Dabigatran: contraindicated if eGFR <30 mL/min (80% renally excreted). Rivaroxaban: avoid if eGFR <15 mL/min for VTE treatment; dose reduce for AF if eGFR 15-49 and creatinine at least 133 umol/L. Apixaban: avoid if eGFR <25 mL/min; dose reduce for AF if 2/3 criteria met (age at least 80, weight at most 60 kg, creatinine at least 133 umol/L) -- 2.5 mg BD. Edoxaban: avoid if eGFR <15 or >95 (paradoxically reduced efficacy at high GFR in AF). Use CrCl (Cockroft-Gault) for DOAC dosing."]','A','Use Cockroft-Gault CrCl for DOAC renal dosing (not eGFR). Dabigatran most renally dependent -- CI at CrCl <30. Apixaban least dependent (27% renal).','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Haematology','Pharmacology','Direct Oral Anticoagulants','easy','flashcard','What are the advantages of DOACs over warfarin?','["(1) Predictable pharmacokinetics -- fixed dosing, no routine monitoring; (2) Fewer drug interactions; (3) No dietary vitamin K interaction; (4) Faster onset of action (no need for heparin bridging); (5) Shorter half-life (easier perioperative management); (6) Better efficacy/safety profile for stroke prevention in AF (ROCKET, ARISTOTLE, RE-LY trials); (7) Lower intracranial haemorrhage rates than warfarin. Disadvantages: cost, no routine monitoring in renal failure, limited data in pregnancy/mechanical valves."]','A','DOACs vs Warfarin: No monitoring, no diet restrictions, fewer drug interactions, lower ICH risk. Disadvantage: cost, no routine monitoring, renal clearance.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Haematology','Pharmacology','Direct Oral Anticoagulants','hard','flashcard','How do you manage perioperative DOAC cessation and resumption?','["General principle: Stop DOAC based on bleeding risk of procedure and DOAC half-life. LOW bleeding risk procedure: Stop 24h before (1-2 half-lives); resume 24h after. HIGH bleeding risk procedure: Stop 48h before (2-4 half-lives); resume 48-72h after. Dabigatran requires longer hold in renal impairment (eGFR 30-50 = hold 4 days). Anti-Xa level or thrombin clotting time can confirm drug clearance pre-procedure. No routine bridging with heparin needed for DOACs -- shorter half-life makes bridging unnecessary."]','A','DOAC periop: stop 24h (low risk) or 48h (high risk) before. No bridging heparin needed. Resume 24-72h post-op. Check renal function for dabigatran.','universal',false,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Haematology','Pharmacology','Direct Oral Anticoagulants','medium','flashcard','What is andexanet alfa and for which DOACs is it licensed?','["Andexanet alfa (Ondexa) is a recombinant modified human factor Xa decoy molecule -- it binds and sequesters anti-Xa DOACs (rivaroxaban, apixaban) and fondaparinux, reversing their anticoagulant effect. Licensed for: rivaroxaban and apixaban in life-threatening or uncontrolled bleeding. Not active against dabigatran (use idarucizumab for dabigatran). Given as IV bolus followed by infusion. 4-factor PCC is an alternative if andexanet alfa unavailable."]','A','Andexanet alfa = recombinant FXa decoy = reverses rivaroxaban and apixaban. Idarucizumab = reverses dabigatran. PCC = non-specific reversal for all DOACs.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Haematology','Pharmacology','Direct Oral Anticoagulants','medium','flashcard','What is the significance of rivaroxaban being taken with food?','["Rivaroxaban bioavailability is dose-dependent and food-dependent: 10 mg and 15 mg tablets: bioavailability approximately 80-100% with or without food. 20 mg tablet (AF dose): bioavailability increases from approximately 66% (fasted) to approximately 100% (fed) -- MUST be taken with the largest meal of the day. Mechanism: food slows gastric emptying and increases dissolution/absorption time for the 20 mg dose. Clinical impact: patients who miss a meal and take 20 mg rivaroxaban may have significantly reduced anticoagulation."]','A','Rivaroxaban 20 mg MUST be taken with food -- bioavailability drops from 100% (fed) to 66% (fasted). Counsel patients every time.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Haematology','Pharmacology','Direct Oral Anticoagulants','easy','flashcard','Which DOACs and at what doses are used for extended VTE secondary prevention?','["Extended VTE prevention (after initial 3-6 months treatment): (1) Rivaroxaban 10 mg OD (EINSTEIN CHOICE trial -- superior to aspirin, similar bleeding risk). (2) Apixaban 2.5 mg BD (AMPLIFY-EXT trial -- reduced recurrence vs placebo, similar bleeding risk). These lower prophylactic doses are used when the risk of VTE recurrence outweighs the bleeding risk but full treatment doses are considered excessive long-term."]','A','Extended VTE prevention: rivaroxaban 10 mg OD or apixaban 2.5 mg BD -- half the treatment dose. Reduces recurrent VTE with lower bleeding risk.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Haematology','Pharmacology','Direct Oral Anticoagulants','hard','flashcard','What drug interactions are important to consider with DOACs?','["All DOACs are P-glycoprotein (P-gp) substrates; rivaroxaban and apixaban also CYP3A4 substrates. AVOID/USE WITH CAUTION: P-gp and CYP3A4 inhibitors (increase DOAC levels => bleeding risk): ketoconazole, itraconazole, HIV protease inhibitors (e.g. ritonavir), dronedarone. P-gp and CYP3A4 inducers (decrease DOAC levels => thrombosis risk): rifampicin, phenytoin, carbamazepine, St John Wort -- AVOID with most DOACs. Combined antithrombotic therapy (aspirin/clopidogrel + DOAC) significantly increases GI bleeding risk."]','A','DOAC killers: P-gp + CYP3A4 inhibitors (azoles, dronedarone) => raise levels => bleed. Inducers (rifampicin, phenytoin) => lower levels => clot. Combine with antiplatelets cautiously.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Haematology','Pharmacology','Antiplatelets','easy','flashcard','What is the mechanism of action of aspirin as an antiplatelet?','["Aspirin (acetylsalicylic acid) irreversibly inhibits cyclo-oxygenase (COX-1 and COX-2) by acetylating a serine residue. COX-1 in platelets produces thromboxane A2 (TXA2) -- a potent vasoconstrictor and platelet aggregator. Platelets are anucleate -- cannot synthesise new COX -- so aspirin effect lasts the platelet lifetime (approximately 7-10 days). At low doses (75-150 mg), aspirin selectively inhibits platelet COX-1, shifting TXA2/PGI2 balance toward antiplatelet/vasodilatory effect."]','A','Aspirin = irreversible COX inhibitor => no TXA2 from platelets (no nucleus = no new COX). Effect lasts 7-10 days (platelet lifespan). Low dose = antiplatelet; high dose = anti-inflammatory.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Haematology','Pharmacology','Antiplatelets','medium','flashcard','What is the mechanism of action of clopidogrel and ticagrelor, and how do they differ?','["Clopidogrel (thienopyridine): prodrug requiring hepatic CYP2C19 activation; active metabolite irreversibly blocks P2Y12 ADP receptor on platelets, preventing ADP-mediated platelet aggregation. Effect lasts platelet lifetime (approximately 7-10 days). CYP2C19 poor metabolisers have reduced efficacy. Ticagrelor (CPTP): not a prodrug; directly and reversibly binds P2Y12 receptor; faster onset, more consistent platelet inhibition; effect wears off in 3-5 days. Both used in ACS."]','A','Both block P2Y12. Clopidogrel = prodrug (CYP2C19) + irreversible. Ticagrelor = direct + reversible (more predictable). Prasugrel also thienopyridine (more potent, more bleeding).','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Haematology','Pharmacology','Antiplatelets','medium','flashcard','What are the indications for dual antiplatelet therapy (DAPT) and how long should it be continued?','["DAPT = aspirin + P2Y12 inhibitor (clopidogrel, ticagrelor, or prasugrel). Indications: (1) ACS (NSTEMI/STEMI): aspirin + ticagrelor (preferred) or prasugrel; continue DAPT for 12 months. (2) PCI with stent: DAPT for 12 months (drug-eluting stent), 1 month (bare metal stent). (3) Ischaemic stroke (non-cardioembolic): aspirin + clopidogrel for 21-90 days (early dual therapy), then aspirin monotherapy. High bleeding risk may shorten DAPT."]','A','ACS: aspirin + ticagrelor/prasugrel x 12 months. Drug-eluting stent: DAPT x 12 months. Stroke: aspirin + clopidogrel x 21-90 days then aspirin alone.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Haematology','Pharmacology','Antiplatelets','hard','flashcard','What is the clinical relevance of CYP2C19 polymorphisms for clopidogrel?','["CYP2C19 poor metabolisers (carrying *2 or *3 loss-of-function alleles -- approximately 25% of Caucasians, approximately 50% of East Asians) cannot adequately convert clopidogrel to its active metabolite, leading to reduced platelet inhibition and increased risk of stent thrombosis and MACE (major adverse cardiovascular events). CYP2C19 *17 ultra-rapid metabolisers: excessive drug activation => higher bleeding risk. Clinical options for poor metabolisers: switch to ticagrelor or prasugrel (not CYP2C19 dependent). FDA black box warning on clopidogrel for CYP2C19 poor metaboliser risk."]','A','Clopidogrel = CYP2C19 prodrug. Poor metabolisers (*2/*3) => less active drug => stent thrombosis risk. Switch to ticagrelor (no CYP2C19 issue). FDA black box warning.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Haematology','Pharmacology','Antiplatelets','medium','flashcard','What are the key adverse effects of ticagrelor that distinguish it from clopidogrel?','["Ticagrelor adverse effects: (1) Dyspnoea -- most distinctive; occurs in approximately 15% of patients (mechanism: adenosine reuptake inhibition => increased circulating adenosine => purinergic receptor activation in lung); usually mild/transient, not bronchospasm. (2) Bradyarrhythmias -- rare, via adenosine mechanism. (3) Increased bleeding (especially GI bleeding). (4) Elevated uric acid/gout. (5) Elevated serum creatinine. Contraindication: previous intracranial haemorrhage, active pathological bleeding."]','A','Ticagrelor unique SEs: dyspnoea (adenosine effect, not bronchospasm) + bradycardia. NOT seen with clopidogrel. Dyspnoea resolves -- do not stop drug unless severe.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Haematology','Pharmacology','Antiplatelets','easy','flashcard','What are the indications, dose, and key adverse effects of aspirin in cardiovascular disease?','["Indications: (1) Secondary prevention of MI, stroke, and peripheral arterial disease (75-150 mg/day); (2) Acute MI/ACS: 300 mg loading dose stat then 75 mg/day; (3) DAPT with P2Y12 inhibitor after ACS/PCI. Key adverse effects: (1) GI bleeding and peptic ulceration -- give PPI with long-term aspirin; (2) Aspirin-exacerbated respiratory disease (via COX-1 inhibition leading to more leukotrienes); (3) Reye syndrome (children <16 with viral illness -- avoid); (4) Renal impairment at high doses."]','A','Aspirin 75 mg/day = secondary prevention. 300 mg loading for ACS. Give PPI to protect GI. Avoid in children (Reye syndrome), asthma (may worsen), third trimester pregnancy.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Haematology','Pharmacology','Antiplatelets','medium','flashcard','What is the mechanism of action of glycoprotein IIb/IIIa inhibitors and when are they used?','["Glycoprotein IIb/IIIa (GPIIb/IIIa) is the final common pathway of platelet aggregation -- fibrinogen and vWF bridge GPIIb/IIIa receptors on adjacent platelets. Drugs: (1) Abciximab -- monoclonal antibody fragment; long effect (receptor blockade 12-24h); (2) Eptifibatide -- cyclic peptide; reversible; (3) Tirofiban -- small molecule; reversible. All given IV. Used in: High-risk NSTEMI/ACS during PCI to prevent platelet aggregation at the stent site."]','A','GPIIb/IIIa = final platelet aggregation pathway (fibrinogen bridge). Abciximab/eptifibatide/tirofiban block it. Used in high-risk PCI (IV only). Risk: thrombocytopenia.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Haematology','Pharmacology','Antiplatelets','medium','flashcard','What is the important drug interaction between aspirin and ibuprofen?','["Ibuprofen (and other non-selective NSAIDs) competitively and reversibly bind COX-1 at the same active site as aspirin. When taken before aspirin, ibuprofen occupies the COX-1 binding site and PREVENTS aspirin from accessing the site to perform its irreversible acetylation. This blocks aspirin antiplatelet effect. Clinical significance: Patients on low-dose aspirin should take aspirin 30 minutes BEFORE ibuprofen (or use paracetamol instead). Regular ibuprofen use antagonises aspirin cardioprotective effect."]','A','Ibuprofen blocks aspirin irreversible COX-1 acetylation -- take aspirin 30 min BEFORE ibuprofen. Better: use paracetamol instead of NSAIDs in aspirin-treated patients.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Haematology','Pharmacology','Antiplatelets','easy','flashcard','How long before surgery should antiplatelet drugs be stopped?','["Aspirin: usually continue for most surgery; STOP 7 days before high-bleeding-risk surgery (e.g. neurosurgery, spinal, ophthalmology). Clopidogrel: stop 7 days before surgery. Ticagrelor: stop 5 days before surgery (reversible, shorter offset). Prasugrel: stop 7 days before surgery. After coronary stent: never stop DAPT within 1 month of bare metal stent or 3-6 months of drug-eluting stent without cardiology advice -- risk of acute stent thrombosis."]','A','Stop before surgery: aspirin 7 days, clopidogrel 7 days, ticagrelor 5 days, prasugrel 7 days. NEVER stop DAPT in recently stented patient without cardiology input.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Haematology','Pharmacology','Antiplatelets','hard','flashcard','What is the mechanism of action and clinical use of dipyridamole?','["Dipyridamole inhibits phosphodiesterase (PDE) preventing breakdown of cAMP in platelets, leading to elevated cAMP, protein kinase A activation, and reduced platelet activation. Also blocks adenosine reuptake, increasing extracellular adenosine, which stimulates A2 receptors, increasing cAMP and causing vasodilation. Clinical use: (1) Combined with aspirin (Asasantin MR) for secondary prevention of ischaemic stroke; (2) Dipyridamole stress test (causes vasodilation -- used in cardiac imaging). Adverse effects: headache, flushing, diarrhoea, dizziness."]','A','Dipyridamole = PDE inhibitor + adenosine uptake blocker => more cAMP => inhibit platelets + vasodilate. Use: aspirin + dipyridamole for secondary stroke prevention. Also coronary vasodilator stress test.','universal',false,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Haematology','Pharmacology','Thrombolytics','easy','flashcard','What is the mechanism of action of thrombolytic agents (fibrinolytics)?','["Thrombolytics activate plasminogen, converting it to plasmin, a serine protease that cleaves fibrin clots (and fibrinogen, factors V, VIII) causing clot dissolution (fibrinolysis). Alteplase (tPA): recombinant tissue plasminogen activator; preferentially activates fibrin-bound plasminogen -- more clot-specific, less systemic fibrinogenolysis. Streptokinase: bacterial protein; binds plasminogen and forms an activator complex; immunogenic; causes systemic fibrinolysis."]','A','Thrombolytics: plasminogen => plasmin => dissolve clot. tPA (alteplase) = clot-specific (fibrin-bound). Streptokinase = systemic, immunogenic, cheaper.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Haematology','Pharmacology','Thrombolytics','medium','flashcard','What are the indications for thrombolytic therapy in clinical practice?','["(1) Acute ischaemic stroke: alteplase IV within 4.5 hours of onset (if CT confirms no haemorrhage, no absolute contraindications); tenecteplase now preferred in some centres. (2) STEMI: if primary PCI unavailable within 120 minutes and patient presents within 12 hours -- streptokinase or alteplase. (3) Massive pulmonary embolism: alteplase 100 mg IV over 2h for haemodynamically unstable PE (SBP <90 mmHg). (4) Catheter-directed thrombolysis: for DVT or submassive PE. (5) Blocked central venous catheters: alteplase."]','A','Thrombolytics: stroke (tPA <4.5h), STEMI (if no PCI in time), massive PE (haemodynamically unstable). Remember: CT head first before stroke thrombolysis.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Haematology','Pharmacology','Thrombolytics','hard','flashcard','What are the absolute contraindications to thrombolytic therapy?','["Absolute contraindications: (1) Any prior intracranial haemorrhage; (2) Known malignant intracranial neoplasm or vascular malformation; (3) Ischaemic stroke within 3 months (except acute presenting stroke being treated <4.5h); (4) Suspected aortic dissection; (5) Active internal bleeding (excluding menses); (6) Significant closed-head trauma within 3 months; (7) Recent intracranial/intraspinal surgery. Relative contraindications: BP >180/110, pregnancy, active peptic ulcer, recent major surgery (10-14 days), CPR >10 min, INR >1.7."]','A','Absolute thrombolytic CIs: prior ICH, active bleeding, aortic dissection, recent head trauma/surgery, brain tumour. Major risk = haemorrhagic transformation.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Haematology','Pharmacology','Thrombolytics','medium','flashcard','How does alteplase differ from streptokinase in clinical use?','["Alteplase (tPA): fibrin-selective (clot-specific), shorter t1/2 approximately 5 min (continuous infusion required), non-immunogenic (can re-use), higher cost. Streptokinase: bacterial (Streptococcal) protein, non-fibrin-selective (systemic fibrinolysis), half-life approximately 23 min, immunogenic (anti-streptokinase antibodies after first use -- contraindicated for repeat use within 12 months), less expensive, more hypotension. Tenecteplase: tPA variant with longer half-life => single IV bolus; similar efficacy to alteplase for STEMI."]','A','Alteplase = fibrin-selective, non-immunogenic, expensive, IV infusion. Streptokinase = non-selective, immunogenic (one-time use), cheap. Tenecteplase = single bolus, preferred in STEMI.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Haematology','Pharmacology','Thrombolytics','medium','flashcard','What is the dose and administration of alteplase for acute ischaemic stroke?','["Alteplase for ischaemic stroke: 0.9 mg/kg IV (maximum 90 mg total). Give 10% of the dose as IV bolus over 1 minute, then the remaining 90% as continuous IV infusion over 60 minutes. Must be given within 4.5 hours of symptom onset. Prerequisites: CT/MRI to exclude haemorrhage; blood pressure <185/110 mmHg before and during treatment; platelets >100 x 10^9/L; INR <1.7; blood glucose 2.8-22.2 mmol/L. Monitor neurological status closely -- if deterioration stop infusion immediately."]','A','Alteplase stroke: 0.9 mg/kg (max 90 mg) -- 10% bolus then 90% over 60 min, within 4.5h. BP <185/110 essential. CT before treatment.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Haematology','Pharmacology','Thrombolytics','medium','flashcard','What are the major adverse effects of thrombolytic therapy?','["(1) Haemorrhage -- most serious. Intracranial haemorrhage (ICH): approximately 6% in stroke; approximately 0.5-1% in MI. GI, retroperitoneal bleeding. (2) Allergic/anaphylactic reactions: mainly with streptokinase (bacterial protein); fever, rash, bronchospasm, hypotension. (3) Reperfusion arrhythmias: after STEMI thrombolysis as coronary flow restored (usually benign accelerated idioventricular rhythm). (4) Hypotension: streptokinase causes histamine release. If major bleed: stop thrombolytic, give cryoprecipitate (fibrinogen), FFP, antifibrinolytics (tranexamic acid)."]','A','Thrombolytic risks: bleeding (ICH most feared), streptokinase = allergic reactions, reperfusion arrhythmias. Stop drug + tranexamic acid + cryoprecipitate for major bleed.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Haematology','Pharmacology','Thrombolytics','easy','flashcard','What is tranexamic acid and how does it work?','["Tranexamic acid (TXA) is a synthetic antifibrinolytic drug. Mechanism: structural analogue of lysine; competitively inhibits plasminogen activation by blocking lysine-binding sites on plasminogen and plasmin, preventing plasmin from binding fibrin, thereby stabilising the clot. Uses: (1) Trauma haemorrhage -- within 3h (CRASH-2 trial); (2) Post-partum haemorrhage (PPH) -- within 3h of delivery; (3) Surgical bleeding (orthopaedic, cardiac surgery, hepatic); (4) Menorrhagia (oral); (5) Hereditary angioedema."]','A','Tranexamic acid = antifibrinolytic (blocks plasmin binding to fibrin). CRASH-2 trial: TXA in trauma reduces death if given <3h. Also PPH, surgery, menorrhagia.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Haematology','Pharmacology','Thrombolytics','hard','flashcard','What is catheter-directed thrombolysis (CDT) and in which conditions is it used?','["CDT involves placing a catheter directly into the clot under imaging guidance and infusing a low dose of thrombolytic (e.g. alteplase) directly into the thrombus over several hours. Advantages over systemic thrombolysis: lower systemic thrombolytic dose => lower bleeding risk; higher local drug concentration at clot site. Indications: (1) Submassive PE (right heart strain but haemodynamically stable); (2) Extensive proximal DVT (iliofemoral) -- to prevent post-thrombotic syndrome; (3) Acute limb ischaemia (peripheral arterial occlusion)."]','A','CDT = thrombolytic directly into clot via catheter. Lower systemic dose = less bleeding risk. Used for submassive PE, iliofemoral DVT, acute limb ischaemia.','universal',false,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Haematology','Pharmacology','Thrombolytics','medium','flashcard','What is the pharmacokinetic advantage of tenecteplase over alteplase in STEMI?','["Tenecteplase (TNK-tPA) is a genetically engineered variant of alteplase with three amino acid changes that confer: (1) Longer half-life (approximately 17-24 min vs 5 min for alteplase) => single IV bolus; (2) Greater fibrin specificity (fibrin-bound plasminogen activation); (3) More resistance to plasminogen activator inhibitor-1 (PAI-1). Single weight-based IV bolus (dose range 30-50 mg based on weight) simplifies pre-hospital administration. ASSENT-2 trial: tenecteplase non-inferior to alteplase for STEMI with fewer non-cerebral bleeds."]','A','Tenecteplase = single bolus (long t1/2), more fibrin-specific, PAI-1 resistant. Preferred for pre-hospital STEMI thrombolysis. Alteplase = 90-min infusion.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Haematology','Pharmacology','Thrombolytics','easy','flashcard','Why is streptokinase contraindicated for repeat use within 12 months?','["Streptokinase is a bacterial (streptococcal) protein and therefore immunogenic. After first exposure, the immune system generates anti-streptokinase antibodies (IgG). These antibodies: (1) Neutralise streptokinase before it can activate plasminogen => reduced or absent therapeutic effect; (2) Can cause severe allergic reactions (anaphylaxis) on re-exposure. Antibody titres remain elevated for at least 12 months. Therefore: streptokinase is effectively a one-lifetime drug. Alteplase and tenecteplase are non-immunogenic and can be repeated if needed."]','A','Streptokinase = immunogenic (bacterial protein) => anti-strep antibodies after first use => no repeat within 12 months (neutralised + anaphylaxis risk). tPA = safe to repeat.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Haematology','Pharmacology','Chemotherapy Principles','easy','flashcard','What is the mechanism of action of alkylating agents and name three examples?','["Alkylating agents form covalent bonds (alkyl groups) with DNA -- primarily at the N-7 position of guanine -- causing: (1) DNA cross-linking (intra-strand and inter-strand); (2) DNA strand breaks; (3) Mispairing leading to mutations. Result: DNA replication is inhibited, causing cell death. Cell cycle non-specific (attack resting and dividing cells). Examples: (1) Cyclophosphamide (nitrogen mustard) -- prodrug, activated by CYP; (2) Chlorambucil -- oral, CLL; (3) Melphalan -- myeloma; (4) Busulfan -- CML/HSCT conditioning; (5) Cisplatin -- cross-links DNA at N-7 guanine."]','A','Alkylators = cross-link DNA = cell cycle non-specific. Cyclophosphamide, melphalan, chlorambucil, busulfan, cisplatin. Toxicity: bone marrow suppression, haemorrhagic cystitis (cyclophosphamide), gonadotoxicity.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Haematology','Pharmacology','Chemotherapy Principles','medium','flashcard','What is the mechanism of action of antimetabolites and provide three haematological examples?','["Antimetabolites are structural analogues of normal cellular metabolites that interfere with DNA/RNA synthesis. Types: (1) Folate antagonists: Methotrexate -- inhibits dihydrofolate reductase (DHFR) => blocks THF synthesis => no purines/thymidylate => DNA synthesis stops. (2) Purine antagonists: 6-Mercaptopurine (6-MP) -- incorporated into DNA; Fludarabine -- inhibits DNA polymerase, used in CLL. (3) Pyrimidine antagonists: Cytarabine (Ara-C) -- inhibits DNA polymerase; incorporated into DNA causing chain termination; mainstay of AML treatment."]','A','Antimetabolites = S-phase specific (DNA synthesis). Methotrexate (DHFR inhibitor), cytarabine (DNA polymerase inhibitor, AML), fludarabine (CLL), 6-MP (ALL, maintenance).','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Haematology','Pharmacology','Chemotherapy Principles','medium','flashcard','What are the mechanisms and examples of topoisomerase inhibitors used in haematology?','["Topoisomerases prevent DNA supercoiling during replication. Inhibitors trap the enzyme-DNA complex, causing permanent DNA strand breaks and cell death. Topoisomerase I inhibitors: Irinotecan, topotecan -- cause single-strand breaks; S-phase specific. Topoisomerase II inhibitors: (1) Etoposide (VP-16) -- causes double-strand breaks; used in lymphoma (CHOP-E regimen), testicular cancer, small cell lung cancer; (2) Anthracyclines -- doxorubicin, daunorubicin, idarubicin -- also intercalate DNA; used in AML, ALL, lymphoma, myeloma. Anthracycline toxicity: cumulative cardiotoxicity (dilated cardiomyopathy)."]','A','Topo II inhibitors: etoposide (lymphoma/germ cell) + anthracyclines (doxorubicin -- AML, lymphoma). Anthracycline cardiotoxicity = cumulative => monitor LVEF before each cycle.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Haematology','Pharmacology','Chemotherapy Principles','medium','flashcard','What are the common dose-limiting toxicities of chemotherapy agents?','["Bone marrow suppression (myelosuppression): most common dose-limiting toxicity leading to neutropaenia (infection risk), thrombocytopaenia (bleeding), anaemia. Nadir: typically 10-14 days after chemotherapy. Specific toxicities: Cardiotoxicity: anthracyclines (doxorubicin -- dilated cardiomyopathy, cumulative dose limit approximately 450 mg/m2). Nephrotoxicity: cisplatin (proximal tubule damage -- prevent with aggressive IV hydration). Peripheral neuropathy: vincristine, cisplatin, bortezomib. Haemorrhagic cystitis: cyclophosphamide (prevent with MESNA). Pulmonary fibrosis: bleomycin."]','A','Dose-limiting toxicities: myelosuppression (most). Anthracyclines = heart (cumulative). Cisplatin = kidneys + neuropathy. Cyclophosphamide = bladder (MESNA prevents it). Bleomycin = lung fibrosis.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Haematology','Pharmacology','Chemotherapy Principles','hard','flashcard','What is tumour lysis syndrome (TLS) and how is it prevented and managed?','["TLS: metabolic emergency from rapid tumour cell destruction leading to release of intracellular contents. Features: Hyperuricaemia (from purine breakdown via xanthine oxidase), Hyperkalaemia (K+ release), Hyperphosphataemia (phosphate release), Hypocalcaemia (phosphate binds Ca2+). Leads to: renal failure (urate crystals), cardiac arrhythmias, seizures. Risk: bulky tumour, high proliferation (ALL, Burkitt lymphoma, DLBCL). Prevention: IV hydration (2-3 L/day), allopurinol (xanthine oxidase inhibitor) or rasburicase (recombinant uricase -- breaks down existing uric acid); avoid exogenous potassium/phosphate."]','A','TLS = HUAK: Hyperuricaemia, Urate nephropathy, Arrhythmia, K+ high. Prevent: IV fluids + allopurinol. Rasburicase = best for high-risk TLS (breaks down uric acid).','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Haematology','Pharmacology','Chemotherapy Principles','easy','flashcard','What is MESNA and why is it used with cyclophosphamide?','["Cyclophosphamide is metabolised by CYP450 in the liver to active acrolein and phosphoramide mustard. Acrolein accumulates in the bladder causing direct mucosal toxicity leading to haemorrhagic cystitis (bloody, painful urination), and long-term risk of urothelial carcinoma. MESNA (2-mercaptoethane sulfonate sodium): given IV or orally at the same time and 4h and 8h after cyclophosphamide. MESNA is inert systemically but concentrated in urine where its free thiol group binds and detoxifies acrolein. Also: adequate IV hydration reduces bladder urotoxicity."]','A','Cyclophosphamide => acrolein => haemorrhagic cystitis. MESNA binds acrolein in urine = uroprotection. Give MESNA with every ifosfamide/cyclophosphamide dose.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Haematology','Pharmacology','Chemotherapy Principles','medium','flashcard','What is the mechanism of action of vinca alkaloids and what is their major toxicity?','["Vinca alkaloids (vincristine, vinblastine, vinorelbine) bind to tubulin and inhibit tubulin polymerisation, disrupting the mitotic spindle and arresting cells in metaphase (M-phase specific agents). Used in: lymphomas (CHOP), ALL (vincristine), testicular cancer (vinblastine). Key toxicity: Vincristine -- peripheral neuropathy (dose-limiting; glove-and-stocking pattern, constipation from autonomic neuropathy); Vinblastine -- myelosuppression (dose-limiting). CRITICAL: vinca alkaloids are for IV use ONLY -- intrathecal administration is FATAL (spinal cord destruction)."]','A','Vinca alkaloids = M-phase specific (spindle poison). Vincristine = neurotoxicity (peripheral neuropathy, constipation). Vinblastine = myelosuppression. NEVER intrathecal -- fatal.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Haematology','Pharmacology','Chemotherapy Principles','hard','flashcard','What is the purpose of colony-stimulating factors (G-CSF, GM-CSF) in chemotherapy?','["G-CSF (granulocyte colony-stimulating factor -- filgrastim, lenograstim, pegfilgrastim): Stimulates production and differentiation of neutrophil precursors, increasing neutrophil count and reducing duration of chemotherapy-induced neutropaenia. GM-CSF (sargramostim): stimulates neutrophils, monocytes, and eosinophils. Uses: (1) Primary prophylaxis with high myelosuppressive regimens (>20% febrile neutropaenia risk -- e.g. CHOP); (2) Secondary prophylaxis after prior febrile neutropaenia; (3) Stem cell mobilisation for PBSC harvesting; (4) Haematopoietic recovery post-HSCT. Adverse effects: bone pain (most common), splenic enlargement/rupture (rare)."]','A','G-CSF (filgrastim/pegfilgrastim) = more neutrophils = shorter neutropaenic period. Give prophylactically with high-risk chemo (>20% FN risk). Bone pain = most common SE.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Haematology','Pharmacology','Chemotherapy Principles','medium','flashcard','What are the mechanisms of drug resistance in cancer chemotherapy?','["Major mechanisms: (1) Decreased drug uptake -- reduced expression of drug transporters; (2) Increased drug efflux -- P-glycoprotein (MDR1/ABCB1) overexpression pumps drugs out of cells; (3) Decreased drug activation -- prodrugs not converted to active form (e.g. 6-MP requires HGPRT); (4) Increased drug inactivation -- glutathione detoxification; (5) Target gene amplification -- DHFR overexpression (methotrexate resistance); (6) Target mutation -- BCR-ABL kinase mutations (imatinib resistance); (7) Enhanced DNA repair; (8) Apoptosis pathway defects (p53 mutation)."]','A','Drug resistance: P-gp efflux pump (MDR1), target mutation (BCR-ABL in imatinib resistance), decreased activation, increased repair. Combination chemotherapy overcomes resistance.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Haematology','Pharmacology','Chemotherapy Principles','easy','flashcard','What is the rationale for combination chemotherapy?','["Combination chemotherapy is used because: (1) Drugs with different mechanisms kill cancer cells via multiple pathways -- prevents/overcomes resistance; (2) Drugs targeting different phases of cell cycle lead to more cells killed at each cycle; (3) Allows use of lower doses of individual agents, reducing toxicity while maintaining overall efficacy; (4) Prevents/delays emergence of resistant clones (single gene mutation unlikely to confer resistance to all drugs simultaneously); (5) Synergistic effects between agents. Design principles: each agent should have activity alone, different mechanisms, non-overlapping toxicities, optimal scheduling."]','A','Combination chemo rationale: multiple MOAs + non-overlapping toxicities + prevent resistance. Example: CHOP (cyclophosphamide + hydroxydoxorubicin + vincristine + prednisolone) for lymphoma.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Haematology','Pharmacology','Haematological Disease-Specific Drugs','medium','flashcard','What is the mechanism of action and clinical use of hydroxyurea in sickle cell disease?','["Hydroxyurea (hydroxycarbamide) is a ribonucleotide reductase inhibitor that: (1) Increases foetal haemoglobin (HbF) production -- HbF does not sickle; (2) Decreases HbS concentration in cells; (3) Reduces neutrophil and platelet count (anti-inflammatory); (4) Increases RBC water content and deformability. Clinical benefits: reduces vaso-occlusive crises by >50%, reduces acute chest syndrome, reduces transfusion need, may reduce mortality. Takes 6-12 weeks to see HbF rise."]','A','Hydroxyurea = increases HbF => reduces sickling. Also reduces WBC/platelets. Benefits: 50% fewer crises. Takes 3 months to work. Monitor FBC regularly.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Haematology','Pharmacology','Haematological Disease-Specific Drugs','medium','flashcard','What is the role of hydroxyurea in chronic myeloid leukaemia (CML) and how does it differ from imatinib?','["Hydroxyurea in CML: reduces WBC count rapidly (cytoreduction) -- used as temporary debulking treatment while awaiting imatinib or other tyrosine kinase inhibitor therapy; does not induce cytogenetic remission or affect the BCR-ABL clone. Does not alter disease course. Imatinib (Gleevec/Glivec): tyrosine kinase inhibitor -- specifically inhibits BCR-ABL, PDGFR, and c-Kit, inducing complete haematological, cytogenetic, and molecular remission in CML. Imatinib is the definitive treatment; hydroxyurea is only a bridge/temporising agent."]','A','Hydroxyurea in CML = cytoreduction only (lower WBC fast). Imatinib = disease-modifying (BCR-ABL inhibitor = complete remission). Hydroxyurea never replaces imatinib in CML.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Haematology','Pharmacology','Haematological Disease-Specific Drugs','easy','flashcard','What is imatinib (Gleevec/Glivec), its mechanism of action, and its primary indication?','["Imatinib is a selective tyrosine kinase inhibitor (TKI). Mechanism: binds the ATP-binding site of the BCR-ABL tyrosine kinase (the abnormal fusion kinase produced by the Philadelphia chromosome t(9;22) translocation in CML), blocking constitutively active kinase, inhibiting downstream cell proliferation and survival signals, and inducing apoptosis of BCR-ABL-positive cells. Also inhibits PDGFR and c-KIT. Primary indications: (1) Chronic myeloid leukaemia (CML) -- Philadelphia chromosome positive; (2) Gastrointestinal stromal tumours (GIST -- c-KIT mutation); (3) Ph+ ALL."]','A','Imatinib = first TKI. BCR-ABL inhibitor. Philadelphia chromosome (t9;22) => BCR-ABL => CML. Imatinib = magic bullet for CML. Oral daily.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Haematology','Pharmacology','Haematological Disease-Specific Drugs','hard','flashcard','What are the mechanisms of imatinib resistance and which second-generation TKIs overcome it?','["Imatinib resistance: most common mechanism = BCR-ABL kinase domain point mutations (e.g. T315I gatekeeper mutation blocks imatinib binding). Others: BCR-ABL gene amplification, clonal evolution, drug efflux (MDR1). Second-generation TKIs: Dasatinib (Sprycel) -- inhibits BCR-ABL + SRC kinases; works in most imatinib-resistant mutants except T315I; good CNS penetration. Nilotinib (Tasigna) -- more selective than imatinib; works in most mutants except T315I. Third-generation: Ponatinib (Iclusig) -- pan-BCR-ABL inhibitor; only approved TKI for T315I mutation."]','A','Imatinib resistance = T315I mutation most common. 2nd gen: dasatinib, nilotinib (not T315I). 3rd gen: ponatinib (works for T315I -- the gatekeeper mutation).','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Haematology','Pharmacology','Haematological Disease-Specific Drugs','medium','flashcard','What is rituximab, its mechanism of action, and its main haematological indications?','["Rituximab (MabThera/Rituxan) is a chimeric anti-CD20 monoclonal antibody (human Fc + mouse Fab). CD20 is expressed on pre-B cells and mature B cells but NOT on stem cells or plasma cells. Mechanism: (1) Complement-dependent cytotoxicity (CDC); (2) Antibody-dependent cellular cytotoxicity (ADCC); (3) Direct induction of apoptosis in B cells. Indications: (1) Non-Hodgkin lymphoma (NHL) -- B-cell types: DLBCL (R-CHOP), follicular lymphoma; (2) Chronic lymphocytic leukaemia (CLL); (3) ITP (immune thrombocytopaenia) -- 2nd line; (4) Autoimmune haemolytic anaemia; (5) Rheumatoid arthritis."]','A','Rituximab = anti-CD20 Ab. Kills B-cells via CDC + ADCC. Used in B-cell NHL (DLBCL, follicular), CLL, ITP, AIHA. CD20 not on stem cells = spares haematopoiesis.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Haematology','Pharmacology','Haematological Disease-Specific Drugs','medium','flashcard','What are the adverse effects and infusion reactions associated with rituximab?','["(1) Infusion-related reactions (most common): fever, chills, rigors, nausea, pruritus, hypotension, bronchospasm -- usually with first infusion; caused by cytokine release; managed by slowing infusion, paracetamol, antihistamines, steroids; pre-medicate before each infusion. (2) Immunosuppression -- B-cell depletion => hypogammaglobulinaemia => increased infection risk. (3) Hepatitis B reactivation -- screen all patients for HBV before rituximab; prophylactic antiviral (entecavir or tenofovir) if HBsAg+ or anti-HBc+. (4) Progressive multifocal leukoencephalopathy (PML) -- JC virus reactivation (rare, serious). (5) Tumour lysis syndrome."]','A','Rituximab SEs: infusion reaction (most common -- first infusion), B-cell depletion, HBV reactivation (screen all patients pre-treatment), PML (JC virus), TLS.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Haematology','Pharmacology','Haematological Disease-Specific Drugs','medium','flashcard','How is dexamethasone used in multiple myeloma and what is its mechanism of benefit?','["Dexamethasone is a potent synthetic glucocorticoid used as a cornerstone of myeloma treatment. Mechanism: (1) Direct pro-apoptotic effect on myeloma cells -- glucocorticoid receptor activation induces apoptosis in plasma cells; (2) Anti-inflammatory -- reduces cytokines (IL-6 is major myeloma growth factor); (3) Synergises with IMiDs (thalidomide, lenalidomide) and proteasome inhibitors (bortezomib). Typical regimens: VCD (bortezomib-cyclophosphamide-dexamethasone); VRd (bortezomib-lenalidomide-dexamethasone). Adverse effects: hyperglycaemia, immunosuppression, steroid psychosis, fluid retention, osteoporosis, peptic ulcer (give PPI cover)."]','A','Dexamethasone in myeloma: pro-apoptotic on plasma cells + anti-IL-6 + synergises with bortezomib/lenalidomide. Used in VRd, VCD regimens. Major SEs: glucose, mood, infection.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Haematology','Pharmacology','Haematological Disease-Specific Drugs','hard','flashcard','What is the mechanism of action of bortezomib (Velcade) and its use in myeloma?','["Bortezomib is a proteasome inhibitor -- first in class. Mechanism: reversibly inhibits the 26S proteasome (specifically the chymotrypsin-like activity of the 20S core). The proteasome is the major intracellular protein degradation pathway. Inhibiting it causes: (1) Accumulation of pro-apoptotic proteins (e.g. p53, p21); (2) Inhibition of NF-kB activation (myeloma cells depend on NF-kB for survival); (3) Accumulation of misfolded proteins leading to endoplasmic reticulum stress and apoptosis. Indications: multiple myeloma, mantle cell lymphoma. SC preferred over IV (less neuropathy)."]','A','Bortezomib = proteasome inhibitor => protein accumulation => NF-kB blocked => apoptosis of plasma cells. Key SE: peripheral neuropathy (reduced with SC administration), thrombocytopenia, herpes zoster reactivation.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Haematology','Pharmacology','Haematological Disease-Specific Drugs','medium','flashcard','What is the role of thrombopoietin receptor agonists (TPO-RAs) in immune thrombocytopaenia (ITP)?','["ITP involves autoantibody-mediated platelet destruction AND impaired megakaryopoiesis. TPO-RA mechanism: bind and activate thrombopoietin receptor (c-Mpl) on megakaryocytes and their precursors, stimulating platelet production to compensate for destruction. Agents: (1) Romiplostim (Nplate) -- peptibody, SC weekly injection; (2) Eltrombopag (Revolade) -- small molecule, oral daily; (3) Avatrombopag -- oral. Indications: chronic ITP (>12 months) refractory to corticosteroids and rituximab. Adverse effects: bone marrow fibrosis (rare), thrombosis, cataracts (eltrombopag), liver enzyme elevation."]','A','TPO-RAs = romiplostim (SC) + eltrombopag (oral). Stimulate platelet production in ITP. Use when steroids + rituximab fail. Risk: marrow fibrosis, thrombosis.','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Lippincott Illustrated Reviews Pharmacology 7th Ed'),
('{"medicine"}','Medicine','Haematology','Pharmacology','Haematological Disease-Specific Drugs','medium','flashcard','What is lenalidomide and how does it work in multiple myeloma?','["Lenalidomide (Revlimid) is an immunomodulatory drug (IMiD) -- an analogue of thalidomide. Mechanism (via cereblon/CRBN binding): (1) Binds cereblon (E3 ubiquitin ligase substrate receptor) redirecting ubiquitin ligase to degrade transcription factors Ikaros (IKZF1) and Aiolos (IKZF3) -- essential for myeloma cell survival -- leading to apoptosis; (2) Anti-angiogenic (reduces VEGF); (3) Immunomodulatory -- enhances T-cell and NK cell activity. Used in: myeloma (maintenance post-ASCT), MDS with del(5q), mantle cell lymphoma. Major adverse effects: DVT (always give VTE prophylaxis), myelosuppression, teratogenicity (strict contraception required via REMS programme)."]','A','Lenalidomide = IMiD. Binds cereblon => degrades IKZF1/IKZF3 => kills myeloma cells. SE: DVT (give LMWH/aspirin), myelosuppression, teratogenic (strict contraception required).','universal',true,'{"year1","year2","year3","year4","year5","year6","practitioner"}','Lippincott Illustrated Reviews Pharmacology 7th Ed');
